def transform_gen(I, O=None, sp=None, marker_rule='always4'):
    from itertools import groupby as gb
    H, W = len(I), len(I[0])
    cnt = Counter(v for r in I for v in r)
    bg = cnt.most_common(1)[0][0]
    runs = []
    for side, cells in [('top',[(0,c) for c in range(W)]), ('bot',[(H-1,c) for c in range(W)]),
                        ('left',[(r,0) for r in range(H)]), ('right',[(r,W-1) for r in range(H)])]:
        for col, grp in gb(cells, key=lambda rc: I[rc[0]][rc[1]]):
            g = list(grp)
            if col != bg and len(g) >= 2:
                runs.append((side, col, g))
    block_cells = {rc for _,_,g in runs for rc in g}
    markers = [(r,c) for r in range(H) for c in range(W) if I[r][c] != bg and (r,c) not in block_cells]
    M = len(markers)
    out = [row[:] for row in I]
    fill = I[markers[0][0]][markers[0][1]] if markers else None
    mset = set(markers)
    def blocked(r,c):
        return (r,c) in block_cells or I[r][c] == fill or (r,c) in mset
    # determine which markers lie on a ray path
    on_ray = set()
    for side, col, cells in runs:
        n = len(cells)
        for i in range(M):
            r0,c0 = cells[min(n-1, sp(i,n,M))]
            dr,dc = {'top':(1,0),'bot':(-1,0),'left':(0,1),'right':(0,-1)}[side]
            r,c = r0+dr, c0+dc
            while 0 <= r < H and 0 <= c < W and not blocked(r,c):
                on_ray.add((r,c))
                r += dr; c += dc
    for r,c in markers:
        if marker_rule=='always4' or (r,c) in on_ray:
            out[r][c] = 4
    for side, col, cells in runs:
        n = len(cells)
        for i in range(M):
            r0,c0 = cells[min(n-1, sp(i,n,M))]
            dr,dc = {'top':(1,0),'bot':(-1,0),'left':(0,1),'right':(0,-1)}[side]
            r,c = r0+dr, c0+dc
            while 0 <= r < H and 0 <= c < W and not blocked(r,c):
                out[r][c] = fill
                r += dr; c += dc
    return out if O is None else (out == O)

